import{_ as p,a0 as o,w as r,s as t,I as e,x as n,a1 as i,A as l,ao as d}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const k=JSON.parse('{"title":"在 Linux 上使用 lspci 命令查看硬件情況 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 上使用 lspci 命令查看硬件情況 | LCTT (202109) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 上使用 lspci 命令查看硬件情況 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 上使用 lspci 命令查看硬件情況 | LCTT (202109) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202109/20210907 Use lspci on Linux to see your hardware","title":"在 Linux 上使用 lspci 命令查看硬件情況","tag":"202109","desc":""},"relativePath":"202109/20210907 Use lspci on Linux to see your hardware.md","filePath":"[post].md"}'),c={name:"202109/20210907 Use lspci on Linux to see your hardware.md"};function u(g,s,h,b,I,v){const a=o("Link");return r(),t("div",null,[s[25]||(s[25]=e("h1",{id:"在-linux-上使用-lspci-命令查看硬件情況",tabindex:"-1"},[n("在 Linux 上使用 lspci 命令查看硬件情況 "),e("a",{class:"header-anchor",href:"#在-linux-上使用-lspci-命令查看硬件情況","aria-label":"Permalink to “在 Linux 上使用 lspci 命令查看硬件情況”"},"​")],-1)),s[26]||(s[26]=e("blockquote",null,[e("p",null,"lspci 命令用於顯示 Linux 系統上的設備和驅動程序。")],-1)),s[27]||(s[27]=e("p",null,[e("img",{src:"https://img.linux.net.cn/data/attachment/album/202109/17/091425l7c8au5c865x7q68.jpg",alt:""})],-1)),e("p",null,[s[1]||(s[1]=n("當你在個人電腦或服務器上運行 Linux 時，有時需要識別該系統中的硬件。",-1)),s[2]||(s[2]=e("code",null,"lspci",-1)),s[3]||(s[3]=n(" 命令用於顯示連接到 PCI 總線的所有設備，從而滿足上述需求。該命令由 ",-1)),i(a,{href:"https://mj.ucw.cz/sw/pciutils/"},{default:l(()=>[...s[0]||(s[0]=[n("pciutils",-1)])]),_:1}),s[4]||(s[4]=n(" 包提供，可用於各種基於 Linux 和 BSD 的操作系統。",-1))]),s[28]||(s[28]=d(`<h3 id="基礎用法" tabindex="-1">基礎用法 <a class="header-anchor" href="#基礎用法" aria-label="Permalink to “基礎用法”">​</a></h3><p>由於訪問權限，普通用户運行 <code>lspci</code> 時顯示的信息可能會受限，因此可以使用 <code>sudo</code> 運行命令，系統會給出完整的信息圖。</p><p>直接運行 <code>lspci</code> 命令會列出 PCI 總線及其連接的設備，下圖是在我的媒體中心 PC 上的演示樣例。圖中是一個基於 AMD Phenom CPU 的系統，所以它有一個 AMD 芯片組，以及 Atheros 無線適配器和 Nvidia 顯卡。所有硬件設備都列出了詳細信息，例如供應商、名稱和型號等：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo lspci</span></span>
<span class="line"><span>00:00.0 Host bridge: Advanced Micro Devices, Inc. [AMD] RS880 Host Bridge</span></span>
<span class="line"><span>00:02.0 PCI bridge: Advanced Micro Devices, Inc. [AMD] RS780 PCI to PCI bridge (ext gfx port 0)</span></span>
<span class="line"><span>00:04.0 PCI bridge: Advanced Micro Devices, Inc. [AMD] RS780/RS880 PCI to PCI bridge (PCIE port 0)</span></span>
<span class="line"><span>00:05.0 PCI bridge: Advanced Micro Devices, Inc. [AMD] RS780/RS880 PCI to PCI bridge (PCIE port 1)</span></span>
<span class="line"><span>00:11.0 SATA controller: Advanced Micro Devices, Inc. [AMD/ATI] SB7x0/SB8x0/SB9x0 SATA Controller [AHCI mode]</span></span>
<span class="line"><span>00:12.0 USB controller: Advanced Micro Devices, Inc. [AMD/ATI] SB7x0/SB8x0/SB9x0 USB OHCI0 Controller</span></span>
<span class="line"><span>00:12.1 USB controller: Advanced Micro Devices, Inc. [AMD/ATI] SB7x0 USB OHCI1 Controller</span></span>
<span class="line"><span>00:12.2 USB controller: Advanced Micro Devices, Inc. [AMD/ATI] SB7x0/SB8x0/SB9x0 USB EHCI Controller</span></span>
<span class="line"><span>00:13.0 USB controller: Advanced Micro Devices, Inc. [AMD/ATI] SB7x0/SB8x0/SB9x0 USB OHCI0 Controller</span></span>
<span class="line"><span>00:13.1 USB controller: Advanced Micro Devices, Inc. [AMD/ATI] SB7x0 USB OHCI1 Controller</span></span>
<span class="line"><span>00:13.2 USB controller: Advanced Micro Devices, Inc. [AMD/ATI] SB7x0/SB8x0/SB9x0 USB EHCI Controller</span></span>
<span class="line"><span>00:14.0 SMBus: Advanced Micro Devices, Inc. [AMD/ATI] SBx00 SMBus Controller (rev 3c)</span></span>
<span class="line"><span>00:14.1 IDE interface: Advanced Micro Devices, Inc. [AMD/ATI] SB7x0/SB8x0/SB9x0 IDE Controller</span></span>
<span class="line"><span>00:14.3 ISA bridge: Advanced Micro Devices, Inc. [AMD/ATI] SB7x0/SB8x0/SB9x0 LPC host controller</span></span>
<span class="line"><span>00:14.4 PCI bridge: Advanced Micro Devices, Inc. [AMD/ATI] SBx00 PCI to PCI Bridge</span></span>
<span class="line"><span>00:14.5 USB controller: Advanced Micro Devices, Inc. [AMD/ATI] SB7x0/SB8x0/SB9x0 USB OHCI2 Controller</span></span>
<span class="line"><span>00:18.0 Host bridge: Advanced Micro Devices, Inc. [AMD] Family 10h Processor HyperTransport Configuration</span></span>
<span class="line"><span>00:18.1 Host bridge: Advanced Micro Devices, Inc. [AMD] Family 10h Processor Address Map</span></span>
<span class="line"><span>00:18.2 Host bridge: Advanced Micro Devices, Inc. [AMD] Family 10h Processor DRAM Controller</span></span>
<span class="line"><span>00:18.3 Host bridge: Advanced Micro Devices, Inc. [AMD] Family 10h Processor Miscellaneous Control</span></span>
<span class="line"><span>00:18.4 Host bridge: Advanced Micro Devices, Inc. [AMD] Family 10h Processor Link Control</span></span>
<span class="line"><span>01:00.0 VGA compatible controller: NVIDIA Corporation GK107 [GeForce GTX 650] (rev a1)</span></span>
<span class="line"><span>01:00.1 Audio device: NVIDIA Corporation GK107 HDMI Audio Controller (rev a1)</span></span>
<span class="line"><span>02:00.0 Network controller: Qualcomm Atheros AR9287 Wireless Network Adapter (PCI-Express) (rev 01)</span></span></code></pre></div><h3 id="詳細輸出" tabindex="-1">詳細輸出 <a class="header-anchor" href="#詳細輸出" aria-label="Permalink to “詳細輸出”">​</a></h3><p>添加 <code>-v</code> 選項會顯示每個設備的詳細信息，你可以使用 <code>-vv</code> 或 <code>-vvv</code> 來獲取更多的設備細節。在 <code>-v</code> 級別，<code>lspci</code> 會顯示所有設備的各種子系統和內存地址、中斷請求（IRQ）編號和一些其他功能信息。輸出信息會非常長。在你的系統上試一試吧。</p><h3 id="使用-grep-過濾搜索" tabindex="-1">使用 grep 過濾搜索 <a class="header-anchor" href="#使用-grep-過濾搜索" aria-label="Permalink to “使用 grep 過濾搜索”">​</a></h3><p>你可能會需要縮小搜索範圍。例如，RPM Fusion 網站有安裝 Nvidia 圖形驅動程序的説明，裏面就首先使用了 <code>grep</code> 命令來定位顯卡信息。下面是我在筆記本電腦上得到的輸出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo lspci | grep -e VGA</span></span>
<span class="line"><span>00:02.0 VGA compatible controller: Intel Corporation UHD Graphics 620 (rev 07)</span></span>
<span class="line"><span>$ sudo lspci | grep -e 3D</span></span>
<span class="line"><span>01:00.0 3D controller: NVIDIA Corporation GM108M [GeForce MX130] (rev a2)</span></span></code></pre></div><p>下面（LCTT 譯註：原文為 “above”，應為作者筆誤）的 <code>grep</code> 命令在我的媒體中心 PC 上定位了一個 VGA 設備，但沒有顯示 3D 設備。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo lspci | grep -e VGA</span></span>
<span class="line"><span>01:00.0 VGA compatible controller: NVIDIA Corporation GK107 [GeForce GTX 650] (rev a1)</span></span>
<span class="line"><span>$ sudo lspci | grep -e 3D</span></span>
<span class="line"><span>$</span></span></code></pre></div><h3 id="按供應商-id-搜索" tabindex="-1">按供應商 ID 搜索 <a class="header-anchor" href="#按供應商-id-搜索" aria-label="Permalink to “按供應商 ID 搜索”">​</a></h3><p>還有另一種無需 <code>grep</code> 的方法可以使用。假設我想確認一下此計算機是否有其他的 Nvidia 設備，在此之前我們還需要一些額外信息，使用 <code>-nn</code> 選項顯示的供應商和設備 ID 號。在我的媒體中心 PC 上，此選項會給出我的 VGA 卡、供應商 ID 和設備 ID：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo lspci -nn | grep -e VGA</span></span>
<span class="line"><span>01:00.0 VGA compatible controller [0300]: NVIDIA Corporation GK107 [GeForce GTX 650] [10de:0fc6] (rev a1)</span></span></code></pre></div><p>設備名稱後的方括號內有用冒號分隔的數字，即供應商和設備 ID。輸出表明 Nvidia Corporation 製造的設備的供應商 ID 為 <code>10de</code>。</p><p><code>-d</code> 選項用於指定供應商、設備或類 ID 的所有設備。以下是我係統中的所有 Nvidia 設備（保留 <code>-nn</code> 以解析供應商 ID）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo lspci -nn -d 10de:</span></span>
<span class="line"><span>01:00.0 VGA compatible controller [0300]: NVIDIA Corporation GK107 [GeForce GTX 650] [10de:0fc6] (rev a1)</span></span>
<span class="line"><span>01:00.1 Audio device [0403]: NVIDIA Corporation GK107 HDMI Audio Controller [10de:0e1b] (rev a1)</span></span></code></pre></div><p>從輸出中可以看到，除了顯卡之外，我還有一個 Nvidia 音頻設備。實際上它們都屬於同一張 <strong>Nvidia GeForce GTX 650</strong> 卡，但這仍然是一個很好的示例。</p><h3 id="內核模組" tabindex="-1">內核模組 <a class="header-anchor" href="#內核模組" aria-label="Permalink to “內核模組”">​</a></h3><p>結合 PCI 硬件設備，<code>lspci</code> 可以使用 <code>-k</code> 選項顯示內核加載了哪些驅動程序模組。我將此選項添加到我的 <code>lspci</code> 命令來查看有關我的 Nvidia 設備的信息。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo lspci -nn -k -d 10de:</span></span>
<span class="line"><span>01:00.0 VGA compatible controller [0300]: NVIDIA Corporation GK107 [GeForce GTX 650] [10de:0fc6] (rev a1)</span></span>
<span class="line"><span> Subsystem: eVga.com. Corp. GK107 [GeForce GTX 650] [3842:2650]</span></span>
<span class="line"><span> Kernel driver in use: nvidia</span></span>
<span class="line"><span> Kernel modules: nvidiafb, nouveau, nvidia_drm, nvidia</span></span>
<span class="line"><span>01:00.1 Audio device [0403]: NVIDIA Corporation GK107 HDMI Audio Controller [10de:0e1b] (rev a1)</span></span>
<span class="line"><span> Subsystem: eVga.com. Corp. GK107 HDMI Audio Controller [3842:2650]</span></span>
<span class="line"><span> Kernel driver in use: snd_hda_intel</span></span>
<span class="line"><span> Kernel modules: snd_hda_intel</span></span></code></pre></div><p>可以看到額外顯示了兩行：<ruby>正在使用的內核驅動程序<rt>Kernel driver in use</rt></ruby> 和 <ruby>內核模組<rt>Kernel modules</rt></ruby>，其中後者列出了可用於支持該設備的模組。</p><h3 id="同步最新狀態" tabindex="-1">同步最新狀態 <a class="header-anchor" href="#同步最新狀態" aria-label="Permalink to “同步最新狀態”">​</a></h3><p>新設備和供應商總是在不斷迭代。如果看到顯示為 <code>unknown</code> 的設備，説明你的 PCI 設備 ID 資料庫可能已過時。有兩種方法可以檢查更新。<code>-Q</code> 選項會使用 DNS 查詢中央資料庫，當然，這需要聯網。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo lspci -Q</span></span></code></pre></div><p>你還可以通過運行命令 <code>update-pciids</code> 來更新本地 PCI ID 資料庫。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo update-pciids</span></span>
<span class="line"><span>Downloaded daily snapshot dated 2021-08-22 03:15:01</span></span></code></pre></div><h3 id="瞭解有關你的硬件的更多信息" tabindex="-1">瞭解有關你的硬件的更多信息 <a class="header-anchor" href="#瞭解有關你的硬件的更多信息" aria-label="Permalink to “瞭解有關你的硬件的更多信息”">​</a></h3>`,28)),e("p",null,[s[6]||(s[6]=n("當然，",-1)),s[7]||(s[7]=e("code",null,"lspci",-1)),s[8]||(s[8]=n(" 只是 Linux 中用於查詢系統硬件和軟件的諸多命令之一。讀者可以在閲讀關於 USB 設備的文章，瞭解有關 Linux 硬件的更多信息：",-1)),i(a,{href:"https://opensource.com/article/20/8/usb-id-repository"},{default:l(()=>[...s[5]||(s[5]=[n("使用此 USB ID 存儲庫識別 Linux 上的更多設備",-1)])]),_:1}),s[9]||(s[9]=n("。",-1))]),s[29]||(s[29]=e("hr",null,null,-1)),e("p",null,[s[11]||(s[11]=n("via: ",-1)),i(a,{href:"https://opensource.com/article/21/9/lspci-linux-hardware"},{default:l(()=>[...s[10]||(s[10]=[n("https://opensource.com/article/21/9/lspci-linux-hardware",-1)])]),_:1})]),e("p",null,[s[16]||(s[16]=n("作者：",-1)),i(a,{href:"https://opensource.com/users/alanfdoss"},{default:l(()=>[...s[12]||(s[12]=[n("Alan Formy-Duval",-1)])]),_:1}),s[17]||(s[17]=n(" 選題：",-1)),i(a,{href:"https://github.com/lujun9972"},{default:l(()=>[...s[13]||(s[13]=[n("lujun9972",-1)])]),_:1}),s[18]||(s[18]=n(" 譯者：",-1)),i(a,{href:"https://github.com/unigeorge"},{default:l(()=>[...s[14]||(s[14]=[n("unigeorge",-1)])]),_:1}),s[19]||(s[19]=n(" 校對：",-1)),i(a,{href:"https://github.com/turbokernel"},{default:l(()=>[...s[15]||(s[15]=[n("turbokernel",-1)])]),_:1})]),e("p",null,[s[22]||(s[22]=n("本文由 ",-1)),i(a,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...s[20]||(s[20]=[n("LCTT",-1)])]),_:1}),s[23]||(s[23]=n(" 原創編譯，",-1)),i(a,{href:"https://linux.cn/"},{default:l(()=>[...s[21]||(s[21]=[n("Linux中國",-1)])]),_:1}),s[24]||(s[24]=n(" 榮譽推出",-1))])])}const D=p(c,[["render",u]]);export{k as __pageData,D as default};
